pub enum Input {
    Php {
        name: String,
        paths: Vec<std::path::PathBuf>,
    },
    TypeScript {
        name: String,
        tsconfig: std::path::PathBuf,
        entry_points: Vec<std::path::PathBuf>,
    },
    Rust {
        name: String,
        rustdoc: Option<std::path::PathBuf>,
        manifest_path: Option<std::path::PathBuf>,
        package: Option<String>,
        toolchain: Option<String>,
        features: Vec<String>,
        all_features: bool,
        no_default_features: bool,
    },
}

pub enum Framework {
    React,
    Vue,
    Svelte,
    Solid,
}

pub enum Language {
    Php,
    TypeScript,
    Rust,
}

pub enum TypeStructure {
    Union {
        types: Vec<Type>,
    },
    Intersection {
        types: Vec<Type>,
    },
    Generic {
        name: String,
        arguments: Vec<Type>,
        argument_parameters: Vec<TypeArgumentParameter>,
    },
}

pub enum SharedTypeStructure {
    Union {
        types: Vec<SharedType>,
    },
    Intersection {
        types: Vec<SharedType>,
    },
    Generic {
        name: String,
        arguments: Vec<SharedType>,
        argument_parameters: Vec<model::TypeArgumentParameter>,
    },
}

